-- Requires the linked boarded-departure source/ride and both spell registrations.
-- Native198941/properties61,vehicle4535,198950 destination and group credit are retained.
-- Never release this file before the matching executable is promoted.
SET @talon_board_concat=@@SESSION.group_concat_max_len;
SET SESSION group_concat_max_len=GREATEST(@@SESSION.group_concat_max_len,1048576);
START TRANSACTION;
